param([string]$Source,[string]$MainTree,[string]$Root)
$ErrorActionPreference='Stop';$errors=$null;$tokens=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($Source,[ref]$tokens,[ref]$errors)
if(@($errors).Count){$errors|Out-String|Out-File (Join-Path $Root parse_failure.txt);exit 1}
$helper=$ast.Find({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Get-ForensicsResourceReservation'},$true)
. ([scriptblock]::Create($helper.Extent.Text))
$header=[regex]::Unescape('# PC \u771f\u5b9e\u8fd0\u884c\u6808\u5360\u7528\u8bb0\u5f55');$reserved=[regex]::Unescape('\u9884\u7559');$released=[regex]::Unescape('\u91ca\u653e')
$line='- 2026-11-17 18:45 +0800 '+$reserved+' / **405test**:owner=Codex `/root/restore403`'
$cases=@(@('405_reserved',@($header,$line),'405',$true),@('403_compatible',@($header,$line.Replace('405test','403test')),'403',$true),@('404_compatible',@($header,$line.Replace('405test','404test')),'404',$true),@('406_compatible',@($header,$line.Replace('405test','406test')),'406',$true),@('405_wrong_card',@($header,$line.Replace('405test','406test')),'405',$false),@('wrong_owner',@($header,$line.Replace('/root/restore403','/root/other')),'405',$false),@('released',@($header,$line.Replace($reserved,$released)),'405',$false),@('history',@($header,$line.Replace($reserved,$released),$line),'405',$false),@('missing_header',@($line),'405',$false),@('empty',@(),'405',$false))
$results=@();foreach($c in $cases){$accepted=$false;$reason='';try{$null=Get-ForensicsResourceReservation -Lines $c[1] -ExpectedCard $c[2];$accepted=$true}catch{$reason=$_.Exception.Message};$results += [ordered]@{case=$c[0];pass=($accepted -eq $c[3]);accepted=$accepted;reason=$reason}}
$actual=@(&git -C $MainTree show origin/main:coord/resources/PC-RUNTIME-STACK.md);if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};$actual|Select-Object -First 5|Out-File (Join-Path $Root actual_resource_utf8.txt) -Encoding utf8
$accepted=$false;$reason='';try{$null=Get-ForensicsResourceReservation -Lines $actual -ExpectedCard '405';$accepted=$true}catch{$reason=$_.Exception.Message}
$guards=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.IfStatementAst] -and ($n.Extent.Text.StartsWith('if ($TestTransitionObserver -and') -or $n.Extent.Text.StartsWith('if ($TestNoActivateGeometry -and') -or $n.Extent.Text.StartsWith('if ($ForensicsCard -eq'))},$true))
$gateCases=@(@('default403',$false,$false,$false,'403',$true),@('old406_explicit',$true,$true,$false,'406',$true),@('geometry405_explicit',$true,$true,$true,'405',$true),@('405_missing_geometry',$true,$true,$false,'405',$false),@('405_missing_observer',$false,$true,$true,'405',$false),@('405_missing_Godot',$true,$false,$true,'405',$false),@('geometry_wrong_card',$true,$true,$true,'406',$false),@('405_only',$false,$false,$false,'405',$false))
$gates=@();foreach($c in $gateCases){$TestTransitionObserver=$c[1];$GodotRestoreForensics=$c[2];$TestNoActivateGeometry=$c[3];$ForensicsCard=$c[4];$ok=$true;try{foreach($g in $guards){. ([scriptblock]::Create($g.Extent.Text))}}catch{$ok=$false};$gates += [ordered]@{case=$c[0];pass=($ok -eq $c[5]);accepted=$ok}}
$bytes=[IO.File]::ReadAllBytes($Source);$ascii=@($bytes|Where-Object {$_ -gt 127}).Count -eq 0
[ordered]@{powershell_version=$PSVersionTable.PSVersion.ToString();acp=[Text.Encoding]::Default.CodePage;parser_errors=0;source_ascii=$ascii;helper_cases=$results;option_gates=$gates;actual405_lease_accepted=$accepted;actual405_lease_expected=$false;actual405_lease_reason=$reason;guard_count=$guards.Count;top_level_invoked=$false;Godot_or_window_started=$false}|ConvertTo-Json -Depth 6|Out-File (Join-Path $Root ps51_geometry_checks.json) -Encoding utf8
if(@($results|Where-Object {-not $_.pass}).Count -or @($gates|Where-Object {-not $_.pass}).Count -or $guards.Count -ne 4 -or $accepted -or -not $ascii){exit 1}